/* Minimal Markdown renderer for this personal blog. */
window.marked={parse:function(s){let e=s.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');e=e.replace(/^###### (.*)$/gm,'<h6>$1</h6>').replace(/^##### (.*)$/gm,'<h5>$1</h5>').replace(/^#### (.*)$/gm,'<h4>$1</h4>').replace(/^### (.*)$/gm,'<h3>$1</h3>').replace(/^## (.*)$/gm,'<h2>$1</h2>').replace(/^# (.*)$/gm,'<h1>$1</h1>');e=e.replace(/^> (.*)$/gm,'<blockquote>$1</blockquote>');e=e.replace(/```([\s\S]*?)```/g,'<pre><code>$1</code></pre>');e=e.replace(/`([^`]+)`/g,'<code>$1</code>');e=e.replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>').replace(/\*([^*]+)\*/g,'<em>$1</em>');e=e.replace(/\[([^\]]+)\]\(([^)]+)\)/g,'<a href="$2">$1</a>');e=e.replace(/^(?:- )(.*)$/gm,'<li>$1</li>');e=e.replace(/(<li>.*<\/li>\n?)+/g,x=>'<ul>'+x+'</ul>');e=e.split(/\n{2,}/).map(x=>/^<h\d|^<blockquote|^<pre|^<ul/.test(x.trim())?x:'<p>'+x.replace(/\n/g,'<br>')+'</p>').join('');return e}};
